mapper.insert:
INSERT INTO storage_blobs (sha256, storage_key, size_bytes, content_type, created_at)
SELECT
    #{sha256}, #{storageKey}, #{sizeBytes}, #{contentType,jdbcType=VARCHAR},
    #{createdAt,typeHandler=org.apache.ibatis.type.InstantTypeHandler}
WHERE NOT EXISTS (
    SELECT 1 FROM storage_blobs WHERE sha256 = #{sha256}
)

mapper.delete:
DELETE FROM storage_blobs
WHERE sha256 = #{sha256}
  AND NOT EXISTS (
      SELECT 1 FROM dataset_files WHERE blob_sha256 = #{sha256}
  )
